type reader struct{b []byte;at int}
func(r *reader)take(n int)[]byte{if n<0||n>len(r.b)-r.at{panic("truncated")};v:=r.b[r.at:r.at+n];r.at+=n;return v}
func(r *reader)item(depth int)any{if depth>16{panic("depth")};c:=r.take(1)[0];m,a:=c>>5,c&31;if m==7{switch a{case 20:return false;case 21:return true;case 22:return nil};panic("simple")};var n uint64;if a<24{n=uint64(a)}else{width:=map[byte]int{24:1,25:2,26:4,27:8}[a];if width==0{panic("indefinite")};for _,v:=range r.take(width){n=n<<8|uint64(v)};if(width==1&&n<24)||(width==2&&n<=255)||(width==4&&n<=65535)||(width==8&&n<=4294967295){panic("nonminimal")}}
 switch m{case 0:if n>9223372036854775807{panic("overflow")};return int64(n);case 1:if n>9223372036854775807{panic("overflow")};return -int64(n)-1;case 3:if n>8192{panic("length")};s:=string(r.take(int(n)));if !utf8.ValidString(s){panic("utf8")};return s;case 4:if n>8192{panic("length")};v:=make([]any,0,int(n));for i:=uint64(0);i<n;i++{v=append(v,r.item(depth+1))};return v;case 5:if n>8192{panic("length")};v:=map[string]any{};for i:=uint64(0);i<n;i++{k,ok:=r.item(depth+1).(string);if !ok{panic("key")};if _,ok=v[k];ok{panic("duplicate")};v[k]=r.item(depth+1)};return v};panic("major")}
func main(){if len(os.Args)!=2{panic("fixture path required")};f,e:=os.Open(os.Args[1]);if e!=nil{panic(e)};defer f.Close();s:=bufio.NewScanner(f);count:=0;for s.Scan(){var row struct{ID,Amount,State,Hex string};if e=json.Unmarshal(s.Bytes(),&row);e!=nil{panic(e)};b,e:=hex.DecodeString(row.Hex);if e!=nil{panic(e)};r:=reader{b:b};v:=r.item(1).(map[string]any);if r.at!=len(b)||v["operation_id"]!=row.ID||v["state"]!=row.State||v["fiscal_reference"]!="FD-1"||v["nullable"]!=nil||len(v["empty"].([]any))!=0{panic("projection")};n,e:=strconv.ParseInt(row.Amount,10,64);if e!=nil{panic(e)};if v["payment_evidence"].([]any)[0].(map[string]any)["amount_minor"]!=n{panic("integer changed")};count++};if e=s.Err();e!=nil{panic(e)};if count!=12{panic("missing cases")};fmt.Println("Independent Go production delivery CBOR:12 exact int64/state/metadata PASS")}
